import{_ as e,o as i,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Crimson/SeaStore Meeting 2022-07-13","description":"","frontmatter":{"title":"Crimson/SeaStore Meeting 2022-07-13","date":"2022-07-13T00:00:00.000Z","updated":"2022-07-20T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可伸缩性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","Bluestore","BlueFS","RocksDB","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","损坏纠正码","复制","快照","克隆","瘦省配额","iSCSI","Fibre Channel","NFS","CIFS","POSIX","监控","仪表板","管理","演示","自动化","集成","容器化","Kubernetes","Docker","虚拟化","云计算","AWS","Azure","Google Cloud","混合云","多云","存储集群","节点","磁盘","SSD","HDD","JBOD","SAN","NAS","网络","拓扑","失效域","恢复","弹性","负载均衡","缓存","压缩","数据去重","分级","性能调优","基准测试","测试","验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Crimson_SeaStore_Meeting_2022-07-13.md","filePath":"posts/2022/Crimson_SeaStore_Meeting_2022-07-13.md","lastUpdated":1780460162000}'),r={name:"posts/2022/Crimson_SeaStore_Meeting_2022-07-13.md"};function o(n,l,s,u,S,h){return i(),a("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间-2022年7月13日" tabindex="-1">会议时间：2022年7月13日 <a class="header-anchor" href="#会议时间-2022年7月13日" aria-label="Permalink to &quot;会议时间：2022年7月13日&quot;">​</a></h4><h4 id="参会人员-列出参会人员" tabindex="-1">参会人员：[列出参会人员] <a class="header-anchor" href="#参会人员-列出参会人员" aria-label="Permalink to &quot;参会人员：[列出参会人员]&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><strong>Ceph多核PR的进展</strong><ul><li>第二个多核PR即将完成，预计明天发布。第三个多核PR的工作即将开始。</li></ul></li><li><strong>OSD启动和ZNS设备测试</strong><ul><li>成功在ZNS设备上启动OSD，并进行了RADOS Bench测试。遇到GC（垃圾回收）问题，需要进一步调试。</li></ul></li><li><strong>对象数据块分割和冲突检测改进</strong><ul><li>第一个PR已合并，后续工作包括进一步改进冲突检测和简化随机块管理器的循环日志。</li></ul></li><li><strong>列表对象和枚举对象的调试</strong><ul><li>正在根据评论修改PR，并进行调试。</li></ul></li><li><strong>物理B3优化和死亡引用问题</strong><ul><li>已分离出第一个PR，第二个PR即将提交。</li></ul></li><li><strong>HDD支持的讨论</strong><ul><li>关于是否在HDD上使用RBM（随机块管理器）进行了深入讨论，建议使用段管理器优化HDD的分配策略。</li></ul></li><li><strong>SMR硬盘支持的可能性</strong><ul><li>提出了在Ceph中支持SMR（叠瓦式磁记录）硬盘的可能性，建议创建SMR实现的段管理器。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>继续调试ZNS设备上的GC问题，并考虑创建相关bug报告。</li><li>继续改进冲突检测和简化随机块管理器的循环日志。</li><li>继续调试列表对象和枚举对象的问题。</li><li>继续优化物理B3和解决死亡引用问题。</li><li>对于HDD支持，建议尽可能避免设备特定代码，并考虑使用段管理器优化HDD的分配策略。</li><li>考虑在Ceph中支持SMR硬盘，创建SMR实现的段管理器。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>发布第二个多核PR，并开始第三个多核PR的工作。</li><li>继续调试ZNS设备上的GC问题，并创建相关bug报告。</li><li>完成冲突检测的改进和随机块管理器的简化。</li><li>完成列表对象和枚举对象的调试。</li><li>提交物理B3优化的第二个PR。</li><li>讨论并实施HDD支持的优化策略。</li><li>研究并实施SMR硬盘的支持。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>会议中提到的技术术语包括ZNS（Zone Namespace）、RADOS Bench、GC（垃圾回收）、RBM（随机块管理器）、SMR（叠瓦式磁记录）等。</li><li>会议结束时间：[具体时间]</li></ul>',11)])])}const _=e(r,[["render",o]]);export{c as __pageData,_ as default};
